	sections = {
		{
			title = "Обзор",
			text = [=[Гномреган был городом {link:gnomes}гномов{/link}, чудом света, встроенным в западные холмы {link:dun-morogh}Дун Морога{/link}. Его залы были полны великих машин, заводных слуг и устройств, какие не приснились бы никакому другому народу. Сегодня это отравленные руины. Его ворота стерегут больные и обезумевшие уцелевшие после его падения, его глубины кишат {link:troggs}троггами{/link} и живой слизью, а в его сердце сидит гном, который его предал.]=],
		},
		{
			title = "Истоки",
			text = [=[{link:gnomes}Гномы{/link} построили Гномреган собственными руками, как соседи и друзья {link:dwarves}дворфов{/link} {link:ironforge}Стальгорна{/link}. Ни одна летопись не называет год его основания. Поколениями он был престолом главного механика и гордостью народа гномов, и из его мастерских вышли многие машины, служившие {link:alliance}Альянсу{/link} во {link:second-war}Вторую войну{/link}.]=],
		},
		{
			title = "Падение",
			text = [=[{link:troggs}Трогги{/link} поднялись из глубин под городом в таком числе, что {link:gnomes}гном{/link}ы не могли их сдержать. Главный механик {link:gelbin-mekkatorque}Гелбин Меггакрут{/link} решил истребить их оружием, которое создали сами гномы. Оно убивало троггов, но убило и великое множество гномов и оставило город пропитанным ядом. Многие из выживших превратились в зараженных, больных телом и пустых разумом. Остальные бежали в {link:ironforge}Стальгорн{/link}. За их спинами мехинженер {link:mekgineer-thermaplugg}Термоштепсель{/link}, которому главный механик доверял, забрал город себе.]=],
		},
		{
			title = "В стенах города",
			text = [=[• {b}Вход.{/b} Гномка Эми Короткий Запал удерживает ворота от {link:troggs}трогг{/link}ов взрывчаткой и очень малым запасом терпения.
• {b}Чистая зона.{/b} Отряд {link:gnomes}гном{/link}ов, которые не сдались, цепляется за комнату, свободную от яда, где странная машина Чистер 5200 до сих пор отмывает и заворачивает все, что в нее кладут.
• {b}Глубины.{/b} Отравленные слизни, сломанные машины и взбунтовавшийся робот Техбот бродят по нижним залам. Некогда он был помощником механиков. Искра перевернула его разум.
• {b}Хозяева.{/b} {link:grubbis}Груббис{/link} ведет троггов города. {link:mekgineer-thermaplugg}Термоштепсель{/link} повелевает зараженными гномами и машинами. {link:dark-iron-dwarves}Дворфы Черного Железа{/link} свободно ходят среди них, и в залах порой встречают посла Черного Железа.]=],
