Translate("ruRU", "viscous-fallout", {
	title = "Вязкая Жижа",
	subtitle = "Живой яд",
	found = "Отравленные глубины Гномрегана",
	allegiance = "Нет",
	sections = {
		{
			title = "Обзор",
			text = [=[Вязкая Жижа — то, что оставила после себя чистка {link:gnomeregan}Гномреган{/link}а. Это колышущаяся масса зеленой слизи, рожденная ядом, который затопил город, и она таится в глубинах, где яд гуще всего. Вокруг нее ползают слизни поменьше и иные твари. {link:gnomes}Гномы{/link}, изучающие яд в {link:kharanos}Каранос{/link}е, хотят получить образцы от таких созданий, взятые свежими, ибо говорят, что осадок с {link:troggs}трогг{/link}ов слишком слаб для их работы.]=],
		},
		{
			title = "Значение",
			text = [=[Вязкая Жижа — собственное оружие {link:gnomes}гном{/link}ов, обретшее тело. Это единственный враг в {link:gnomeregan}Гномреган{/link}е, в котором нельзя винить никого другого.]=],
		},
	},
})

